/bin/zsh -lc "node --input-type=module -e '
import { registerHooks } from \"node:module\";
import { existsSync } from \"node:fs\";
registerHooks({resolve(spec,ctx,next){
 if(spec.endsWith(\".js\")&&ctx.parentURL?.startsWith(\"file:\")){
 const url=new URL(spec.replace(/\\\\.js"'$/,".ts"),ctx.parentURL);
 if(existsSync(url))return next(url.href,ctx);
 } return next(spec,ctx);
}});
const {priceWithCoupons,CouponError}=await import("./src/pricing/coupon.ts");
const items=Object.freeze([Object.freeze({sku:"A",name:"A",unitPrice:1000,quantity:2})]);
const coupons=Object.freeze([Object.freeze({scope:"order",type:"rate",value:10}),Object.freeze({scope:"item",sku:"A",type:"fixed",value:100})]);
const before=JSON.stringify([items,coupons]);
console.log("frozen inputs",priceWithCoupons(items,coupons),"unchanged",JSON.stringify([items,coupons])===before);
for(const value of [NaN,Infinity,-Infinity]){
 for(const field of ["value","maxDiscount","minOrder"]){
 const c={scope:"order",type:"fixed",value:1,[field]:value};
 try{priceWithCoupons(items,[c]); console.log("unexpected accept",field,String(value));}catch(e){console.log(field,String(value),e instanceof CouponError);}
 }
}
for(const value of [1,100])console.log("valid rate",value,priceWithCoupons(items,[{scope:"order",type:"rate",value,minOrder:0}]));
const base=Number.MAX_SAFE_INTEGER,percent=99;
console.log("large rate expected",String(BigInt(base)*BigInt(percent)/100n),"actual",priceWithCoupons([{sku:"A",name:"A",unitPrice:base,quantity:1}],[{scope:"order",type:"rate",value:percent}]));
'"'"

